def canonical(value):
    return json.dumps(value,sort_keys=True,separators=(',',':'),ensure_ascii=True,allow_nan=False).encode('ascii')
def unique_pairs(pairs):
    out={}
    for k,v in pairs:
        if k in out: raise ValueError('duplicate JSON key')
        out[k]=v
    return out
def read_json_safe(path, maximum=4*1024*1024):
    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_CLOEXEC)
    try:
        st=os.fstat(fd)
        if not stat.S_ISREG(st.st_mode) or st.st_uid!=0 or st.st_gid!=0 or st.st_size>maximum:
            raise ValueError('unsafe JSON file identity: '+path)
        chunks=[]
        while True:
            b=os.read(fd,65536)
            if not b: break
            chunks.append(b)
        raw=b''.join(chunks)
        if len(raw)!=st.st_size: raise ValueError('JSON size changed: '+path)
    finally: os.close(fd)
    return json.loads(raw,object_pairs_hook=unique_pairs,parse_constant=lambda _: (_ for _ in ()).throw(ValueError('nonfinite JSON'))),raw
def fingerprint(path):
    try: before=os.lstat(path)
    except FileNotFoundError: return {'kind':'absent'}
    meta={'uid':before.st_uid,'gid':before.st_gid,'mode':stat.S_IMODE(before.st_mode),'size':before.st_size,'device':before.st_dev,'inode':before.st_ino}
    if stat.S_ISLNK(before.st_mode): return {'kind':'symlink',**meta}
    if not stat.S_ISREG(before.st_mode): return {'kind':'other',**meta}
    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_CLOEXEC)
    try:
        opened=os.fstat(fd)
        if (opened.st_dev,opened.st_ino)!=(before.st_dev,before.st_ino): raise ValueError('file changed while opening: '+path)
        h=hashlib.sha256(); total=0
        while True:
            b=os.read(fd,65536)
            if not b: break
            total+=len(b); h.update(b)
        after=os.fstat(fd); path_after=os.lstat(path)
        if (after.st_dev,after.st_ino,after.st_size,after.st_mtime_ns)!=(opened.st_dev,opened.st_ino,opened.st_size,opened.st_mtime_ns) or (path_after.st_dev,path_after.st_ino)!=(opened.st_dev,opened.st_ino) or total!=opened.st_size:
            raise ValueError('file changed while hashing: '+path)
    finally: os.close(fd)
    return {'kind':'regular','uid':opened.st_uid,'gid':opened.st_gid,'mode':stat.S_IMODE(opened.st_mode),'size':total,'device':opened.st_dev,'inode':opened.st_ino,'sha256':h.hexdigest()}
